<script setup lang="ts">
import PmsTableControls from './PmsTableControls.vue';import {ref,onMounted,watch,computed} from 'vue';import {pmsApi} from './api';const tablePage=ref(1),tableSize=ref(10),search=ref('');const filtered=computed(()=>rows.value.filter(r=>Object.values(r).join(' ').toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?filtered.value:filtered.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const tasks=ref<any[]>([]),subtasks=ref<any[]>([]);const data=ref<any>(null),overview=ref<any>(null),rows=ref<any[]>([]),busy=ref(false),error=ref(''),total=ref(0),start=ref(0),filters=ref({company_id:'',project_id:'',task_id:'',subtask_id:'',department_id:'',user_id:'',from_date:'',to_date:'',deadline_health:''});const columns:any={company_name:'Company',project_name:'Project',department_name:'Department',title:'Title',type:'Type',status:'Status',deadline_health:'Deadline',due_date:'Due date',assignee:'Assignee',worked_by:'Worked by',invest_time:'Logged Time'};async function load(reset=true){if(reset){start.value=0;tablePage.value=1;}busy.value=true;try{const query=new URLSearchParams(filters.value);const [summary,result]=await Promise.all([pmsApi('reports/overview?'+query),pmsApi('reports/data?'+query+'&start=0&length=2147483647')]);overview.value=summary;rows.value=result.data;total.value=result.recordsFiltered;error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}watch(()=>filters.value.project_id,async id=>{filters.value.task_id='';filters.value.subtask_id='';tasks.value=[];subtasks.value=[];if(id)try{tasks.value=await pmsApi('reports/tasks?project_id='+id);}catch(e){error.value=(e as Error).message;}});
watch(()=>filters.value.task_id,async id=>{filters.value.subtask_id='';subtasks.value=[];if(id)try{subtasks.value=await pmsApi('reports/subtasks?task_id='+id);}catch(e){error.value=(e as Error).message;}});
watch(()=>filters.value.company_id,()=>{filters.value.project_id='';});
function exportUrl(format:string){return '/pms/api/reports/export/'+format+'?'+new URLSearchParams(filters.value);}
async function copyReport(){try{const result=await pmsApi('reports/data?'+new URLSearchParams(filters.value)+'&start=0&length=2147483647');const text=[Object.values(columns).join('\t'),...result.data.map((r:any)=>Object.keys(columns).map(k=>r[k]??'').join('\t'))].join('\n');await navigator.clipboard.writeText(text);}catch(e){error.value=(e as Error).message;}}
function page(step:number){start.value+=step*25;load(false);}onMounted(async()=>{try{data.value=(await pmsApi('reports')).data;await load();}catch(e){error.value=(e as Error).message;}});
</script><template><div class="admin-section-heading"><h2>Project Reports</h2></div><p v-if="error" class="notice admin-error">{{error}}</p><form class="card p-3 my-3 pms-report-filters" @submit.prevent="load()"><div class="editor-actions"><label v-for="(list,key) in {company_id:'companies',project_id:'projects',department_id:'departments',user_id:'users'}" :key="key">{{{company_id:'Company',project_id:'Project',department_id:'Department',user_id:'Employee'}[key]}}<select v-model="filters[key]"><option value="">All</option><option v-for="r in (list==='projects'&&filters.company_id?data?.projects.filter((p:any)=>p.company_id===Number(filters.company_id)):data?.[list])" :key="r.id" :value="r.id">{{r.name||r.dept_name}}</option></select></label><label>Task<select v-model="filters.task_id" :disabled="!filters.project_id"><option value="">All tasks</option><option v-for="t in tasks" :key="t.id" :value="t.id">{{t.title}}</option></select></label><label>Subtask<select v-model="filters.subtask_id" :disabled="!filters.task_id"><option value="">All subtasks</option><option v-for="t in subtasks" :key="t.id" :value="t.id">{{t.title}}</option></select></label><label>Work from<input type="date" v-model="filters.from_date"></label><label>Work to<input type="date" v-model="filters.to_date" :min="filters.from_date"></label><label>Deadline<select v-model="filters.deadline_health"><option value="">All</option><option v-for="h in ['on_track','overdue','met','late','no_deadline']" :key="h" :value="h">{{h.split('_').join(' ')}}</option></select></label><div class="pms-filter-actions"><button class="button" type="button" @click="filters={company_id:'',project_id:'',task_id:'',subtask_id:'',department_id:'',user_id:'',from_date:'',to_date:'',deadline_health:''};load()">Reset</button><button class="button primary" :disabled="busy">Apply filters</button></div></div></form><div v-if="overview" class="row g-3 mb-4"><div v-for="(label,key) in {total:'Total work items',completed:'Completed',overdue:'Overdue',dueSoon:'Due next 7 days',loggedSeconds:'Hours logged'}" :key="key" class="col"><div class="card p-3"><small>{{label}}</small><h3>{{key==='loggedSeconds'?(overview.summary[key]/3600).toFixed(1):overview.summary[key]}}</h3></div></div></div><div v-if="overview" class="card p-4 mb-4 pms-department-performance"><div class="d-flex justify-content-between mb-3"><div><h5>Department performance</h5><small class="text-muted">Progress and missed deadlines for the selected period</small></div><span class="badge bg-label-primary">{{overview.summary.progress}}% complete</span></div><div v-for="d in overview.departments" :key="d.department" class="mb-3"><div class="d-flex justify-content-between mb-1"><strong>{{d.department}}</strong><span>{{d.completed}} / {{d.total}} completed &middot; {{d.overdue}} overdue</span></div><div class="progress"><div class="progress-bar" :style="{width:d.progress+'%'}"></div></div></div><p v-if="!overview.departments.length" class="text-muted">No department data for these filters.</p></div><p v-if="busy" role="status">Loading report...</p><div class="pms-table-card"><PmsTableControls :total="filtered.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"><details class="pms-export-menu"><summary class="button">Export</summary><div><button @click="copyReport">Copy</button><a v-for="f in ['csv','xlsx','pdf']" :key="f" :href="exportUrl(f)">{{f.toUpperCase()}}</a></div></details></PmsTableControls><table class="pms-table"><thead><tr><th>#</th><th v-for="(label,key) in columns" :key="key">{{label}}</th></tr></thead><tbody><tr v-for="(row,index) in paged" :key="index"><td>{{(tablePage-1)*Math.max(tableSize,0)+index+1}}</td><td v-for="(_,key) in columns" :key="key">{{row[key]}}</td></tr><tr v-if="!rows.length"><td colspan="12">No results match these filters.</td></tr></tbody></table><PmsTableControls footer :total="filtered.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template>